import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArrayRealVector_getNorm_TriageGen2Test {

    private static final double EPSILON = 1e-12;











    @Test
    public void testGetNormWithLargeValues() {
        double[] data = {1e10, 1e10};
        ArrayRealVector vector = new ArrayRealVector(data);
        // sqrt(1e20 + 1e20) = sqrt(2 * 1e20) = 1e10 * sqrt(2)
        double expected = Math.sqrt(2.0) * 1e10;
        Assert.assertEquals(expected, vector.getNorm(), 1e-2); // Larger epsilon for scale
    }




}

